import React from 'react';

function formatInline(text: string, keyPrefix: string): React.ReactNode[] {
  const parts = text.split(/(\*\*[^*]+\*\*|#[^\s#]+)/g);
  return parts.map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={`${keyPrefix}-b-${i}`}>{part.slice(2, -2)}</strong>;
    }
    if (part.startsWith('#') && part.length > 1) {
      return (
        <span key={`${keyPrefix}-tag-${i}`} className="inline-hashtag">
          {part}
        </span>
      );
    }
    return <React.Fragment key={`${keyPrefix}-t-${i}`}>{part}</React.Fragment>;
  });
}

function formatBlock(block: string, bi: number): React.ReactNode {
  const trimmed = block.trim();
  const headerMatch = trimmed.match(/^\*\*(.+)\*\*$/);
  if (headerMatch) {
    return (
      <h5 key={bi} className="message-section-title">
        {headerMatch[1]}
      </h5>
    );
  }

  const isList = /^(\d+[.、]|\*|-|•)\s/m.test(trimmed);
  if (isList) {
    const items = trimmed.split('\n').filter((l) => l.trim());
    return (
      <ul key={bi} className="message-list">
        {items.map((line, li) => {
          const cleaned = line.replace(/^(\d+[.、]|\*|-|•)\s*/, '');
          return <li key={li}>{formatInline(cleaned, `${bi}-${li}`)}</li>;
        })}
      </ul>
    );
  }

  const lines = trimmed.split('\n');
  return (
    <p key={bi} className="message-paragraph">
      {lines.map((line, li) => (
        <React.Fragment key={li}>
          {li > 0 && <br />}
          {formatInline(line, `${bi}-${li}`)}
        </React.Fragment>
      ))}
    </p>
  );
}

/** 将 bot 回复转为分段、标题与列表，提升长文可读性 */
export function formatBotMessage(text: string): React.ReactNode {
  const sections = text.split(/\n---\n/).filter((s) => s.trim());

  return sections.map((section, si) => {
    const blocks = section.split(/\n\n+/).filter((b) => b.trim());
    return (
      <div key={si} className="message-section">
        {blocks.map((block, bi) => formatBlock(block, si * 100 + bi))}
      </div>
    );
  });
}
